// Single-cycle pulse on a rising edge of `din`.
module edge_detector (
    input  logic clk,
    input  logic rst_n,
    input  logic din,
    output logic pulse
);
    logic din_q;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            din_q <= 1'b0;
        end else begin
            din_q <= din;
        end
    end

    assign pulse = din && !din_q;

`ifdef FORMAL
  // ---- generated by formalsynapse.sva_lower; do not edit ----
